INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z12-q365','nism-5a-z12','An investor redeems 230 units at an NAV of ₹31.40 with an exit load of 1%. The amount received (before tax) is:','["₹7,222.00","₹7,294.22","₹7,149.78","₹6,992.00"]',2,'230 × 31.40 × 0.99.',365) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
