INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z12-q371','nism-5a-z12','A goal costs ₹54,000 today. With inflation of 7% p.a., its cost after 12 years will be approximately:','["₹1,30,132","₹1,13,662","₹1,21,618","₹99,360"]',2,'FV = 54000 × (1 + 7%)^12.',371) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
